(() => {
'use strict';const result=document.querySelector('#copyOutputResult');let prepared=null,objectURL=null;
function status(text){result.hidden=false;result.replaceChildren();const p=document.createElement('p');p.textContent=text;result.append(p)}
function snapshot(){const page=window.HVTCopyPage.snapshot();if(!page||!page.text.trim())throw Error('Hãy nhập nội dung trang chép trước.');return page}
function downloadable(blob,name){if(objectURL)URL.revokeObjectURL(objectURL);objectURL=URL.createObjectURL(blob);const a=document.createElement('a');a.href=objectURL;a.download=name;a.textContent='Tải '+name;a.className='text-link';result.append(a);return a}
async function prepare(kind){const page=snapshot(),blob=await(kind==='docx'?window.HVTExports.docxBlob(page):window.HVTExports.pdfBlob(page)),name='Hieu-va-Thuong-Trang-'+page.page+'.'+kind;prepared={blob,name,signature:JSON.stringify(page)};return prepared}
function shareReady(file){const button=document.createElement('button');button.type='button';button.className='button primary';button.textContent='Mở bảng chia sẻ file · Zalo / Email / Messenger';button.onclick=async()=>{try{if(JSON.stringify(snapshot())!==prepared.signature){status('Trang chép vừa thay đổi. Nhấn Chia sẻ file để tạo lại bản mới.');return}await navigator.share({title:'Trang chép Kinh · Hiểu và Thương',files:[file]});}catch(e){if(e.name!=='AbortError')status('Thiết bị chưa chia sẻ được file này. Tải file xuống rồi đính kèm trong Zalo, email hoặc Messenger.')}};result.append(document.createElement('br'),button)}
document.querySelectorAll('[data-copy-output]').forEach(button=>button.onclick=async()=>{const kind=button.dataset.copyOutput;try{if(kind==='print'){const page=snapshot(),popup=window.open('','_blank');if(!popup)throw Error('Trình duyệt chặn cửa sổ in. Cho phép cửa sổ bật lên rồi thử lại.');const d=popup.document;d.open();d.write('<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Trang chép Kinh</title><link rel="stylesheet" href="/copy-print.css"></head><body></body></html>');d.close();const h=d.createElement('h1');h.textContent=page.title;const meta=d.createElement('p');meta.className='meta';meta.textContent='Trang chép '+page.page+' · '+page.source;const body=d.createElement('main');body.innerHTML=window.HVTRich.clean(page.html);const b=d.createElement('button');b.textContent='In / Lưu PDF';b.onclick=()=>popup.print();d.body.append(h,meta,b,body);popup.focus();const sheet=d.querySelector('link');sheet.onload=()=>popup.print();status('Đã mở bản in. Chọn máy in hoặc Lưu thành PDF trong hộp thoại.');return}
status('Đang tạo file có định dạng và font tiếng Việt…');const fileKind=kind==='docx'?'docx':'pdf';const output=await prepare(fileKind);status('Đã tạo file từ nội dung trang đang mở.');downloadable(output.blob,output.name);if(kind==='share'){const file=new File([output.blob],output.name,{type:output.blob.type||'application/pdf'});if(navigator.canShare?.({files:[file]})&&navigator.share){status('File PDF đã sẵn sàng. Nhấn nút bên dưới và chọn ứng dụng nhận.');downloadable(output.blob,output.name);shareReady(file)}else{const p=document.createElement('p');p.textContent='Thiết bị không hỗ trợ chia sẻ file trực tiếp từ trình duyệt. Tải file ở trên và đính kèm vào Zalo, email hoặc Messenger.';result.append(p)}}else result.querySelector('a').click();
}catch(error){status(error.message||'Chưa xuất được file. Vui lòng thử lại.')}});
window.addEventListener('pagehide',()=>{if(objectURL)URL.revokeObjectURL(objectURL)});
})();
